// decoded into a BrainArtifact and re-marshaled to the SAME bytes. A gap here means
// the struct path and the raw-bytes path disagree, so a signature produced by one
// would not verify against the other.
func FuzzCanonicalMarshalRoundTrip(f *testing.F) {
	f.Add([]byte(`{"brain_schema_version":"1.0","manifest":{"repo_key":"gh/o/r","generated_at":"2026-01-02T03:04:05Z"}}`))
	f.Add([]byte(`{"brain_schema_version":"1.0","manifest":{"repo_key":"r","generated_at":"2026-01-02T03:04:05Z"},"snapshots":[{"branch":"main","ref":{"digest":"sha256:ab","size":3}}]}`))

	f.Fuzz(func(t *testing.T, raw []byte) {
		canon, err := Canonicalize(raw)
		if err != nil {
			return
		}
		var a BrainArtifact
		if err := CanonicalUnmarshal(canon, &a); err != nil {
			t.Fatalf("canonical bytes failed to decode into BrainArtifact: %v\ncanon=%q", err, canon)
		}
		again, err := CanonicalMarshal(a)
		if err != nil {
			t.Fatalf("decoded artifact failed to re-marshal: %v\ncanon=%q", err, canon)
		}
		if !bytes.Equal(canon, again) {
			t.Fatalf("struct path and bytes path disagree:\ncanon=%q\nagain=%q", canon, again)
		}
	})
}
